<template>
  <view class="container">
    <view class="return-to-orders-section">
      <button class="return-to-orders-btn" @click="returnToOrders">返回订单列表</button>
    </view>
    <!-- 头部 -->
    <!-- <view class="header"><text class="title">订单详情</text><uni-icons type="more" color="#999" size="20"></uni-icons></view> -->

    <!-- 订单号 + 状态 -->
    <view class="order-info">
      <view class="header-row">
        <text class="label">订单号</text>
        <view class="status-tag" :class="getStatusClass(order.status)">
          {{ getStatusText(order.status) }}
        </view>
      </view>
      <text class="order-number">{{ order.orderId }}</text>
    </view>

    <!-- 服务信息 -->
    <view class="service-info">
      <view class="info-item">
        <text class="label">服务类型：</text>
        <text class="value">{{ order.serviceType }}</text>
      </view>
      <view class="info-item">
        <text class="label">服务时间：</text>
        <text class="value">{{ order.serviceDate }} {{ order.startTime }}</text> <!-- 从 order.vue 结构读取 -->
      </view>
      <view class="info-item">
        <text class="label">服务医院：</text>
        <text class="value">{{ order.hospitalName }}</text>
      </view>
      <view class="info-item">
        <text class="label">服务对象：</text>
        <text class="value">{{ order.contactPerson || order.serviceTarget }}</text> <!-- 优先使用 contactPerson -->
      </view>
      <view class="info-item">
        <text class="label">其他要求：</text>
        <text class="value">{{ order.otherRequirement || '无' }}</text>
      </view>
    </view>

    <!-- 陪诊师信息 -->
    <view class="companion-info">
      <!-- 使用从后端获取的头像路径 -->
      <!-- 重要：使用 v-if 确保 image 元素存在，即使 src 为空 -->
      <image
        v-if="companionAvatar"
        :src="companionAvatar"
        class="avatar"
        mode="aspectFill"
        @error="handleImageError"
      ></image>
      <image
        v-else
        src="/static/default-avatar.jpg"
        class="avatar"
        mode="aspectFill"
      ></image>
      <view class="companion-details">
        <text class="name">{{ companion.name }}</text>
        <view class="phone" v-if="order.status !== 'assigned'">
          <image src="/static/contact.png" class="phone-icon"></image>
          <text class="phone-number">{{ companion.phone }}</text> <!-- 修改：同步电话信息 -->
        </view>
        <view class="rating">
          <text class="star">⭐</text>
          <text class="score">{{ companion.rating }}</text>
        </view>
      </view>
    </view>

    <!-- 支付信息 -->
    <view class="payment-info">
      <view class="payment-row">
        <text class="label">支付金额</text>
        <text class="price">{{ order.price }}</text> <!-- 直接显示 price 字符串 -->
      </view>
      <view class="payment-row">
        <text class="label">支付方式</text>
        <text class="method">{{ order.paymentMethod }}</text>
      </view>
      <view class="payment-row">
        <text class="label">支付时间</text>
        <text class="time">{{ order.payTime }}</text>
      </view>
    </view>

    <!-- 服务记录 -->
    <view class="record-section">
      <view class="record-title">服务记录</view>
      <view class="record-list">
        <view
          v-for="(item, index) in serviceSteps"
          :key="index"
          class="step-item"
        >
          <view class="step-dot"></view>
          <view class="step-content">
            <text class="step-title">{{ item.title }}</text>
            <text class="step-desc">{{ item.desc }}</text>
          </view>
          <text class="step-time">{{ item.time }}</text>
        </view>
      </view>
    </view>

    <!-- 新增：取消订单按钮 -->
    <view class="cancel-order-section" v-if="showCancelButton">
      <button class="cancel-order-btn" @click="cancelOrder">取消订单</button>
    </view>

    <!-- 底部固定导航栏 -->
    <view class="bottom-nav">
      <view class="nav-item" @click="callCompanion">
        <image src="/static/contact.png" class="nav-icon"></image>
        <text>联系</text>
      </view>
      <view class="nav-item" @click="consult">
        <image src="/static/advisory.png" class="nav-icon"></image>
        <text>咨询</text>
      </view>
      <view class="nav-item" @click="evaluate">
        <image src="/static/valuation.png" class="nav-icon"></image>
        <text>评价</text>
      </view>
      <view class="nav-item" @click="share">
        <image src="/static/share.png" class="nav-icon"></image>
        <text>分享</text>
      </view>
    </view>
  </view>
</template>

<script setup>
import { ref, computed } from 'vue';
import { onLoad } from '@dcloudio/uni-app';
import { get, config } from '@/utils/api.js'; // ✅ 新增：导入 config 配置

// 使用 ref 定义响应式变量
const order = ref({});
const companion = ref({ name: '', phone: '', rating: '4.9' }); // 默认信息

// 使用 ref 定义响应式变量，用于存储头像路径
const companionAvatar = ref(null); // 初始化为 null

// 服务记录 (根据订单状态和时间计算)
const serviceSteps = computed(() => {
  if (!order.value) return []; // 如果订单数据未加载，返回空数组

  const steps = [];

  // 根据订单状态动态生成服务记录
  switch (order.value.status) {
    case 'pending': // 待支付
      steps.push(
        { title: '订单创建', desc: '您已成功提交订单', time: '' },
        { title: '待支付', desc: '请在规定时间内完成支付', time: '' }
      );
      break;
    case 'assigned': // 待陪诊师接单
      steps.push(
        { title: '订单创建', desc: '您已成功提交订单', time: '' },
        { title: '已支付', desc: '订单已支付，等待陪诊师接单', time: '' } // 修改此处
      );
      break;
    case 'in_progress': // 进行中
      steps.push(
        { title: '订单创建', desc: '您已成功提交订单', time: '' },
        { title: '陪诊师已接单', desc: '陪诊师已接单，准备为您服务', time: '' },
        { title: '陪诊师预计到达', desc: '陪诊师预计于 14:30 到达医院', time: '14:30' },
        { title: '陪诊师已到达', desc: '陪诊师已抵达医院，等待就诊', time: '15:00' },
        { title: '服务进行中', desc: '陪诊师正在陪同就诊', time: '15:15' }
      );
      break;
    case 'completed': // 已完成
      steps.push(
        { title: '订单创建', desc: '您已成功提交订单', time: '' },
        { title: '陪诊师已接单', desc: '陪诊师已接单，准备为您服务', time: '' },
        { title: '陪诊师预计到达', desc: '陪诊师预计于 09:00 到达医院', time: '09:00' },
        { title: '陪诊师已到达', desc: '陪诊师已抵达医院，等待就诊', time: '09:30' },
        { title: '服务进行中', desc: '陪诊师正在陪同就诊', time: '10:00' },
        { title: '服务已完成', desc: '陪诊服务已结束', time: '10:30' }
      );
      break;
    case 'cancelled': // 已取消
      steps.push(
        { title: '订单创建', desc: '您已成功提交订单', time: '' },
        { title: '订单已取消', desc: '订单已被取消', time: '' }
      );
      break;
    default: // 默认情况，显示基础信息
      steps.push({ title: '订单创建', desc: '您已成功提交订单', time: '' });
  }

  return steps;
});

// 状态映射
const getStatusText = (status) => {
  switch (status) {
    case 'assigned':
      return '待陪诊师接单';
    case 'pending':
      return '待支付';
    case 'cancelled':
      return '已取消';
    case 'in_progress':
      return '进行中';
    case 'completed':
      return '已完成';
    default:
      return '未知';
  }
};

const getStatusClass = (status) => {
  return `status-${status}`;
};

// 新增：计算是否显示取消订单按钮
const showCancelButton = computed(() => {
  // 例如：只有在 '待陪诊师接单' 状态下才显示取消按钮
  return order.value && order.value.status === 'assigned';
});

// 新增：取消订单逻辑
const cancelOrder = () => {
  uni.showModal({
    title: '确认取消',
    content: '您确定要取消此订单吗？',
    success: (res) => {
      if (res.confirm) {
        // 这里执行取消订单的逻辑
        console.log('用户确认取消订单，订单号:', order.value?.orderId);

        // 1. 更新本地缓存中的订单状态
        if (order.value?.orderId) {
          // 更新全局订单列表
          let allOrders = uni.getStorageSync('all_orders') || [];
          const index = allOrders.findIndex((o) => o.id === order.value.orderId);
          if (index !== -1) {
            allOrders[index].status = 'cancelled';
            uni.setStorageSync('all_orders', allOrders);
          }

          // 更新特定订单缓存
          const specificOrderKey = `order_${order.value.orderId}`;
          const specificOrderData = uni.getStorageSync(specificOrderKey);
          if (specificOrderData) {
            specificOrderData.status = 'cancelled';
            uni.setStorageSync(specificOrderKey, specificOrderData);

            // 也更新orderConfirmData，如果这是当前订单
            if (uni.getStorageSync('orderConfirmData')?.orderNo === order.value.orderId) {
              uni.setStorageSync('orderConfirmData', specificOrderData);
            }
          }

          // 更新当前页面数据
          order.value.status = 'cancelled';

          // 可以在这里添加Toast提示
          uni.showToast({
            title: '订单已取消',
            icon: 'success',
          });

          // 可以选择是否自动返回上一页
          // setTimeout(() => {
          //   uni.navigateBack();
          // }, 1500);
        }
      } else if (res.cancel) {
        console.log('用户取消取消操作');
      }
    },
  });
};

// 新增：返回订单列表的方法
const returnToOrders = () => {
  // 使用 reLaunch 确保回到 order.vue 页面
  uni.reLaunch({
    url: '/pages/order/order',
  });
};

// 从后端 API 加载订单详情
const fetchOrderDetail = async (orderNo) => {
  try {
    console.log('【OrderDetailPage】正在调用后端接口获取订单完整信息:', orderNo);
    const response = await get(`/ai/guide/orders/${orderNo}/complete-info`);

    console.log('【OrderDetailPage】后端返回的订单完整数据:', response.data);

    if (response && response.data) {
      // 直接赋值后端返回的完整数据
      const backendData = response.data;

      // --- 重要：处理后端返回的字段并映射到页面结构 ---
      // 注意：这里假设后端返回的字段可以直接映射，或者需要特殊处理
      order.value = {
        orderId: backendData.orderNo || '未知订单号',
        status: mapOrderStatus(backendData.orderStatus), // 将后端状态码映射为前端状态
        serviceType: backendData.serviceTypeName || '普通陪诊',
        serviceDate: backendData.serviceDate || '未知日期',
        startTime: backendData.serviceTime?.split('-')[0] || '未知时间', // 假设 serviceTime 是 "08:00:00-10:00:00"
        hospitalName: backendData.hospital || '未知医院',
        contactPerson: backendData.patientName || '未知对象', // 优先使用患者姓名
        price: `¥${(backendData.totalPrice).toFixed(2)}`, // 假设 totalPrice 以分为单位
        paymentMethod: '微信支付', // 固定值
        payTime: backendData.createTime || new Date().toLocaleString(), // 使用创建时间
        otherRequirement: backendData.otherRequirement, // 新增字段

        // --- 陪诊师信息 ---
        attendantName: backendData.attendantName || '未知陪诊师',
        attendantPhone: backendData.attendantPhone || '未知电话',
        attendantAvatar: backendData.attendantAvatar, // 后端返回的头像路径
        rating: backendData.attendantScore?.toString() || '4.9',
      };

      // 更新 companion 对象
      companion.value = {
        name: order.value.attendantName,
        phone: order.value.attendantPhone,
        rating: order.value.rating,
      };

      // --- 重要：设置陪诊师头像路径 (✅ 按陪诊师列表逻辑修复) ---
      // 1. 优先使用后端返回的头像路径
      let avatarPath = null;
      if (order.value.attendantAvatar) {
        avatarPath = order.value.attendantAvatar;
        console.log('【OrderDetailPage】从 attendantAvatar 获取头像路径:', avatarPath);
      }

      // 2. 如果没有后端返回的路径，则根据陪诊师姓名获取头像路径
      if (!avatarPath && order.value.attendantName) {
        avatarPath = `/static/avatar_${order.value.attendantName}.jpg`;
        console.log('【OrderDetailPage】根据陪诊师姓名获取头像路径:', avatarPath);
      }

      // 3. 处理最终的头像路径 (✅ 核心：复制陪诊师列表的拼接逻辑)
      if (avatarPath) {
        // 检查是否是完整 URL
        if (avatarPath && !avatarPath.startsWith('http')) {
          // 如果是相对路径，去掉开头的 / (统一格式)
          if (avatarPath.startsWith('/')) {
            avatarPath = avatarPath.substring(1);
          }
          // 标准化 baseURL (确保末尾有 /)
          const normalizedBaseUrl = config.baseURL.endsWith('/') ? config.baseURL : config.baseURL + '/';
          // 拼接完整 URL
          avatarPath = normalizedBaseUrl + avatarPath;
        }
        console.log('【OrderDetailPage】拼接后的完整头像路径:', avatarPath);
        companionAvatar.value = avatarPath;
      } else {
        // 如果都找不到，使用默认头像 (同样拼接 baseURL)
        console.log('【OrderDetailPage】无头像路径，使用默认头像');
        const normalizedBaseUrl = config.baseURL.endsWith('/') ? config.baseURL : config.baseURL + '/';
        companionAvatar.value = normalizedBaseUrl + 'static/default-avatar.jpg';
      }

      console.log('【OrderDetailPage】最终设置的头像路径:', companionAvatar.value);

    } else {
      console.warn('【OrderDetailPage】后端返回数据为空或格式不正确:', response);
      uni.showToast({
        title: '获取订单信息失败',
        icon: 'none'
      });
    }
  } catch (error) {
    console.error('【OrderDetailPage】获取订单完整信息失败:', error);
    uni.showToast({
      title: '网络错误，获取订单信息失败',
      icon: 'none'
    });
  }
};

// 将后端状态码映射为前端状态
const mapOrderStatus = (backendStatus) => {
  switch (backendStatus) {
    case 1: return 'assigned'; // 待接单
    case 2: return 'pending'; // 待支付
    case 3: return 'in_progress'; // 进行中
    case 4: return 'completed'; // 已完成
    case 5: return 'cancelled'; // 已取消
    default: return 'assigned'; // 默认状态
  }
};

// 图片加载错误处理 (调试用)
const handleImageError = (e) => {
  console.error('【OrderDetailPage】头像图片加载失败:', e);
  console.log('当前尝试加载的头像路径:', companionAvatar.value);
};

// 底部按钮事件
const callCompanion = () => {
  if (companion.value.phone && order.value.status !== 'assigned') {
    uni.makePhoneCall({
      phoneNumber: companion.value.phone,
    });
  } else {
    uni.showToast({
      title: order.value.status === 'assigned' ? '待陪诊师接单，暂不可联系' : '未获取到陪诊师电话',
      icon: 'none',
    });
  }
};

const consult = () => {
  uni.showToast({
    title: '暂未开放咨询功能',
  });
};

const share = () => {
  uni.showToast({
    title: '暂未开放分享功能',
  });
};

// 跳转到评价页
const evaluate = () => {
  if (!order.value?.orderId) {
    uni.showToast({
      title: '订单ID缺失，无法评价',
      icon: 'none',
    });
    return;
  }
  uni.navigateTo({
    url: '/pages/Evaluate/Evaluate',
  });
};

// 页面加载时从后端 API 读取数据，接收 URL 参数
onLoad(async (options) => {
  const passedOrderNo = options.orderNo || options.orderId;
  console.log('【OrderDetailPage】onLoad 接收到的参数:', options);
  console.log('【OrderDetailPage】提取的订单号 (passedOrderNo):', passedOrderNo);

  if (!passedOrderNo) {
    console.error('【OrderDetailPage】缺少订单号参数');
    uni.showToast({
      title: '订单号错误',
      icon: 'none'
    });
    uni.redirectTo({
      url: '/pages/index/index'
    });
    return;
  }

  // 调用 API 获取订单详情
  await fetchOrderDetail(passedOrderNo);
});
</script>

